class Solution {
public:
    int boxDelivering(vector<vector<int>>& boxes, int portsCount,
                      int maxBoxes, int maxWeight) {
        int n = boxes.size();
        vector<long long> W(n + 1, 0);
        vector<int> P(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            W[i] = W[i - 1] + boxes[i - 1][1];
            P[i] = P[i - 1] + ((i >= 2 && boxes[i - 1][0] != boxes[i - 2][0]) ? 1 : 0);
        }
        vector<long long> dp(n + 1, LLONG_MAX);
        dp[0] = 0;
        for (int j = 1; j <= n; j++) {
            for (int i = j - 1; i >= 0 && j - i <= maxBoxes && W[j] - W[i] <= maxWeight; i--) {
                dp[j] = min(dp[j], dp[i] + 2 + P[j] - P[i]);
            }
        }
        return (int)dp[n];
    }
};

