class Solution {
public:
    int boxDelivering(vector<vector<int>>& boxes, int portsCount,
                      int maxBoxes, int maxWeight) {
        int n = boxes.size();
        vector<long long> W(n + 1, 0);
        vector<int> P(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            W[i] = W[i - 1] + boxes[i - 1][1];
            P[i] = P[i - 1] + ((i >= 2 && boxes[i - 1][0] != boxes[i - 2][0]) ? 1 : 0);
        }
        vector<int> dp(n + 1, 0);
        deque<int> dq;
        int left = 0;
        for (int j = 1; j <= n; j++) {
            while (W[j] - W[left] > maxWeight) left++;
            int lo = max(left, j - maxBoxes);
            while (!dq.empty() && dq.front() < lo) dq.pop_front();
            long long key = dp[j - 1] - P[j - 1];
            while (!dq.empty() && dp[dq.back()] - P[dq.back()] >= key) dq.pop_back();
            dq.push_back(j - 1);
            dp[j] = 2 + P[j] + dp[dq.front()] - P[dq.front()];
        }
        return dp[n];
    }
};

