class Solution {
    public int boxDelivering(int[][] boxes, int portsCount,
                             int maxBoxes, int maxWeight) {
        int n = boxes.length;
        long[] W = new long[n + 1];
        int[] P = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            W[i] = W[i - 1] + boxes[i - 1][1];
            P[i] = P[i - 1] + (i >= 2 && boxes[i - 1][0] != boxes[i - 2][0] ? 1 : 0);
        }
        int[] dp = new int[n + 1];
        Deque<Integer> dq = new ArrayDeque<>();
        int left = 0;
        for (int j = 1; j <= n; j++) {
            while (W[j] - W[left] > maxWeight) left++;
            int lo = Math.max(left, j - maxBoxes);
            while (!dq.isEmpty() && dq.peekFirst() < lo) dq.pollFirst();
            int idx = j - 1;
            long key = dp[idx] - P[idx];
            while (!dq.isEmpty() && dp[dq.peekLast()] - P[dq.peekLast()] >= key) dq.pollLast();
            dq.addLast(idx);
            dp[j] = 2 + P[j] + dp[dq.peekFirst()] - P[dq.peekFirst()];
        }
        return dp[n];
    }
}

