    for (let i = 1; i <= n; i++) {
        W[i] = W[i - 1] + boxes[i - 1][1];
        P[i] = P[i - 1] + (i >= 2 && boxes[i - 1][0] !== boxes[i - 2][0] ? 1 : 0);
    }
    const dp = new Array(n + 1).fill(0);
    const dq = [];
    let head = 0, left = 0;
    for (let j = 1; j <= n; j++) {
        while (W[j] - W[left] > maxWeight) left++;
        const lo = Math.max(left, j - maxBoxes);
        while (head < dq.length && dq[head] < lo) head++;
        const key = dp[j - 1] - P[j - 1];
        while (dq.length > head && dp[dq[dq.length - 1]] - P[dq[dq.length - 1]] >= key) dq.pop();
        dq.push(j - 1);
        dp[j] = 2 + P[j] + dp[dq[head]] - P[dq[head]];
    }
    return dp[n];
};
